import type { GeneratedTestPlan, TestScenario } from '../schemas/ai-output.schemas.js';

export const DRAFT_BANNER = `/**
 * ⚠️  GENERATED DRAFT – REQUIRES HUMAN REVIEW BEFORE ENTERING THE REGRESSION SUITE.
 * Generated by the framework's test-generation tooling. Steps are documented as
 * test.step() blocks with TODO markers where application-specific code is needed.
 * Move to tests/ only after review, implementation and a green run.
 */`;

const quote = (value: string) => `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;

const comment = (value: string) => value.replace(/\*\//g, '*\\/').replace(/\r?\n/g, ' ');

function renderScenario(scenario: TestScenario, fixtures: string): string {
  const tags = [
    ...new Set([
      `@${scenario.layer}`,
      ...scenario.tags,
      ...(scenario.type === 'negative' ? ['@negative'] : []),
    ]),
  ];
  const steps = scenario.steps
    .map(
      (step, i) => `    await test.step(${quote(`${i + 1}. ${step}`)}, async () => {
      // TODO: implement using page objects / API clients
    });`,
    )
    .join('\n');
  const expectations = scenario.expectedResults.map((r) => `    // EXPECT: ${comment(r)}`).join('\n');
  const preconditions = scenario.preconditions.map((p) => `    // PRECONDITION: ${comment(p)}`).join('\n');
  return `  // Traceability: ${comment(scenario.traceability.join(', '))} | priority: ${scenario.priority} | type: ${scenario.type}
  test(${quote(`${scenario.id} ${scenario.title}`)}, { tag: ${JSON.stringify(tags)} }, async ({ ${fixtures} }) => {
${preconditions ? `${preconditions}\n` : ''}${steps}
${expectations}
    test.fixme(true, 'Generated draft: implement steps and assertions, then remove this line');
  });`;
}

/** Renders a test plan as a Playwright spec draft that follows framework conventions. */
export function renderSpecDraft(
  plan: GeneratedTestPlan,
  options: { describe: string; layer?: 'ui' | 'api' | 'e2e' },
): string {
  const scenarios = options.layer ? plan.scenarios.filter((s) => s.layer === options.layer) : plan.scenarios;
  const fixturesFor = (s: TestScenario) =>
    s.layer === 'api'
      ? 'userApi, testData'
      : s.layer === 'e2e'
        ? 'page, userApi, userService, testData'
        : 'page, testData';
  return `${DRAFT_BANNER}
import { test, expect } from '../tests/fixtures/framework.fixture.js';

// Summary: ${comment(plan.summary)}
test.describe(${quote(options.describe)}, () => {
${scenarios.map((s) => renderScenario(s, fixturesFor(s))).join('\n\n')}
});

void expect; // remove once assertions are implemented
`;
}
